def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    monitor_patches = image_patch.find("pc monitor")
    other_patches = image_patch.find("other")

    if not monitor_patches or len(other_patches) < 2:
        return image_patch

    monitor = monitor_patches[0]
    other_centers = [(p.left + p.right) / 2, (p.lower + p.upper) / 2 for p in other_patches]

    min_distance = float('inf')
    closest_other = None

    for center in other_centers:
        dist = abs(center[0] - monitor.horizontal_center)
        if dist < min_distance:
            min_distance = dist
            closest_other = center

    second_closest_other = None
    second_min_distance = float('inf')

    for center in other_centers:
        if center != closest_other:
            dist = abs(center[0] - monitor.horizontal_center)
            if dist < second_min_distance:
                second_min_distance = dist
                second_closest_other = center

    if closest_other[0] < monitor.horizontal_center < second_closest_other[0]:
        return monitor
    elif second_closest_other[0] < monitor.horizontal_center < closest_other[0]:
